#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    vector<int> getSumAbsoluteDifferences(vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;
        long long pref = 0;
        vector<int> res(n, 0);
        for (int i = 0; i < n; ++i) {
            long long x = nums[i];
            long long left_sum = (long long)i * x - pref;
            long long right_sum = (total - pref - x) - (long long)(n - 1 - i) * x;
            res[i] = left_sum + right_sum;
            pref += x;
        }
        return res;
    }
};

class Solution {
    public int[] getSumAbsoluteDifferences(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int x : nums) total += x;
        long pref = 0;
        int[] res = new int[n];
        for (int i = 0; i < n; ++i) {
            long x = nums[i];
            long leftSum = (long)i * x - pref;
            long rightSum = (total - pref - x) - (long)(n - 1 - i) * x;
            res[i] = (int)(leftSum + rightSum);
            pref += x;
        }
        return res;
    }
}

/**
 * @param {number[]} nums
 * @return {number[]}
 */
var getSumAbsoluteDifferences = function(nums) {
    const n = nums.length;
    let total = 0;
    for (const x of nums) total += x;
    let pref = 0;
    const res = Array(n).fill(0);
    for (let i = 0; i < n; ++i) {
        const x = nums[i];
        const leftSum = i * x - pref;
        const rightSum = (total - pref - x) - (n - 1 - i) * x;
        res[i] = leftSum + rightSum;
        pref += x;
    }
    return res;
};
